/*
 * "The Meridian Chart" — a maritime/aeronautical navigation-chart instrument
 * aesthetic, built ONLY for /singapore-vps-hosting. Every rule here is scoped
 * under .sheet (a CSS Module class, so it's uniquely hashed at build time and
 * cannot leak onto — or be overridden by — app/globals.css or any other page).
 *
 * Palette (chosen fresh for this page — no navy/violet/cyan brand tokens):
 *   --paper       #f2ecdd  aged chart paper
 *   --paper-dim   #e7dfc7  recessed panel paper (tables, legend)
 *   --ink         #1e2a22  deep chart ink (near-black, warm green-black)
 *   --ink-soft    #4b5a4e  secondary ink (body copy)
 *   --rule        #c9bd9c  hairline rule / grid color
 *   --vermillion  #c1440e  plotted course / "live" marker / primary CTA ink
 *   --brass       #8a6a2f  measurement ticks, stamps, secondary accent
 */

.sheet {
  --paper: #f2ecdd;
  --paper-dim: #e7dfc7;
  --ink: #1e2a22;
  --ink-soft: #4b5a4e;
  --rule: #c9bd9c;
  --vermillion: #c1440e;
  --brass: #8a6a2f;

  position: relative;
  background-color: var(--paper);
  color: var(--ink);
  font-family: var(--sgp-font-mono), ui-monospace, monospace;
  isolation: isolate;
}

/* Static paper grain — texture only, never animated. */
.sheet::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.5;
  mix-blend-mode: multiply;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='matrix' values='0 0 0 0 0.11  0 0 0 0 0.14  0 0 0 0 0.12  0 0 0 0.05 0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  background-size: 180px 180px;
}

.serif {
  font-family: var(--sgp-font-serif), Georgia, "Times New Roman", serif;
}

.mono {
  font-family: var(--sgp-font-mono), ui-monospace, monospace;
}

.rail {
  position: relative;
  z-index: 1;
  max-width: 78rem;
  margin: 0 auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}

.hairline {
  border-color: var(--rule);
}

/* ---------------------------------------------------------------------- */
/* Reveal — "ruler unrolling" clip-path wipe, not fade+rise.               */
/* ---------------------------------------------------------------------- */
.reveal {
  clip-path: inset(0 100% 0 0);
  opacity: 0.001;
  transition: clip-path 0.9s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.2s linear;
}
.revealShown {
  clip-path: inset(0 0 0 0);
  opacity: 1;
}
@media (prefers-reduced-motion: reduce) {
  .reveal,
  .revealShown {
    clip-path: none;
    opacity: 1;
    transition: none;
  }
}

/* ---------------------------------------------------------------------- */
/* Hero                                                                    */
/* ---------------------------------------------------------------------- */
.heroGrid {
  display: grid;
  gap: 3rem;
  align-items: start;
}
@media (min-width: 1024px) {
  .heroGrid {
    grid-template-columns: 1.05fr 0.95fr;
    gap: 2.5rem;
  }
}

.fixHeader {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--vermillion);
  font-weight: 600;
}
.fixDot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--vermillion);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--vermillion) 25%, transparent);
}
@media (prefers-reduced-motion: no-preference) {
  .fixDot {
    animation: fix-blink 3.4s ease-in-out infinite;
  }
}
@keyframes fix-blink {
  0%, 60%, 100% { opacity: 1; }
  30% { opacity: 0.25; }
}

.h1 {
  margin-top: 1rem;
  font-weight: 600;
  line-height: 0.98;
  letter-spacing: -0.01em;
  font-size: clamp(2.4rem, 6vw, 4.4rem);
  color: var(--ink);
}
.h1 em {
  font-style: italic;
  font-weight: 500;
  color: var(--vermillion);
}

.sub {
  margin-top: 1.5rem;
  max-width: 40rem;
  font-size: 1.02rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

.ctaRow {
  margin-top: 2.25rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
}

.tab {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.85rem 1.4rem;
  font-family: var(--sgp-font-mono), monospace;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border: 1.5px solid var(--ink);
  color: var(--paper);
