}
.tab:hover {
  transform: translate(-2px, -2px);
  background: var(--vermillion);
  border-color: var(--vermillion);
}
.tabGhost {
  composes: tab;
  background: transparent;
  color: var(--ink);
}
.tabGhost:hover {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}

/* ---------------------------------------------------------------------- */
/* Plotting board (SVG)                                                    */
/* ---------------------------------------------------------------------- */
.board {
  position: relative;
  border: 1.5px solid var(--ink);
  background: var(--paper-dim);
  padding: 0.9rem;
}
.board::before,
.board::after,
.boardCornerTL,
.boardCornerBR {
  content: "";
  position: absolute;
  width: 14px;
  height: 14px;
  border: 1.5px solid var(--brass);
}
.board::before { top: -1.5px; left: -1.5px; border-right: none; border-bottom: none; }
.board::after { bottom: -1.5px; right: -1.5px; border-left: none; border-top: none; }

.boardCaption {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-soft);
  padding: 0 0.35rem 0.5rem;
  border-bottom: 1px solid var(--rule);
  margin-bottom: 0.6rem;
}

.courseLine {
  stroke: var(--vermillion);
  stroke-width: 1.4;
  fill: none;
  stroke-dasharray: 4 3;
}
@media (prefers-reduced-motion: no-preference) {
  .courseLineAnim {
    transition: stroke-dashoffset 1.4s cubic-bezier(0.16, 1, 0.3, 1);
  }
}
.gridLine {
  stroke: var(--rule);
  stroke-width: 1;
}
.cityDot {
  fill: var(--ink);
}
.originDot {
  fill: var(--vermillion);
}
.cityLabel {
  font-family: var(--sgp-font-mono), monospace;
  fill: var(--ink);
  font-size: 11px;
}
.distLabel {
  font-family: var(--sgp-font-mono), monospace;
  fill: var(--brass);
  font-size: 9.5px;
  font-weight: 600;
}

@media (prefers-reduced-motion: no-preference) {
  .needle {
    transform-origin: center;
    animation: settle 1.6s cubic-bezier(0.22, 1, 0.36, 1) both;
  }
}
@keyframes settle {
  0% { transform: rotate(-70deg); }
  100% { transform: rotate(0deg); }
}

/* ---------------------------------------------------------------------- */
/* Legend (feature strip as a chart key)                                   */
/* ---------------------------------------------------------------------- */
.legend {
  border-top: 1.5px solid var(--ink);
  border-bottom: 1.5px solid var(--ink);
}
.legendRow {
  display: grid;
  grid-template-columns: 2.75rem 1fr;
  gap: 1rem;
  padding: 1.1rem 0.25rem;
  border-top: 1px solid var(--rule);
  align-items: start;
}
.legendRow:first-child {
  border-top: none;
}
.legendGlyph {
  color: var(--vermillion);
}
.legendTerm {
  font-family: var(--sgp-font-serif), serif;
  font-weight: 600;
  font-size: 1rem;
  color: var(--ink);
}
.legendDef {
  margin-top: 0.3rem;
  font-size: 0.85rem;
  line-height: 1.55;
  color: var(--ink-soft);
}

/* ---------------------------------------------------------------------- */
/* Manifest (pricing)                                                      */
/* ---------------------------------------------------------------------- */
.manifest {
  display: grid;
  gap: 1px;
  background: var(--ink);
  border: 1.5px solid var(--ink);
}
@media (min-width: 900px) {
  .manifest {
    grid-template-columns: repeat(4, 1fr);
