"use client";

import { useEffect, useRef, useState } from "react";
import styles from "./chart.module.css";

/**
 * Page-local scroll reveal: a "ruler unrolling" left-to-right clip-path wipe
 * (see .reveal / .revealShown in chart.module.css) — deliberately not the
 * shared fade+rise <Reveal> used by the rest of the site, and not the old
 * radar-sweep motion either. Falls back to fully visible without JS or when
 * IntersectionObserver is unavailable.
 */
export function RevealChart({
  children,
  delay = 0,
  className = "",
  as: Tag = "div",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
  as?: React.ElementType;
}) {
  const ref = useRef<HTMLElement | null>(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") {
      setShown(true);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            setShown(true);
            io.disconnect();
          }
        }
      },
      { threshold: 0.15, rootMargin: "0px 0px -60px 0px" },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <Tag
      ref={ref}
      className={`${styles.reveal} ${shown ? styles.revealShown : ""} ${className}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {children}
    </Tag>
  );
}

/**
 * Real, computed geography — no invented performance numbers.
 *
 * Great-circle distance (haversine) and initial bearing from Nxeon's Singapore
 * datacenter to each regional city, computed from public city coordinates.
 * Timezone offsets are each city's standard UTC offset. This replaces the old
 * page's dotted-map "latency by country" table, which asserted specific
 * millisecond figures Nxeon has never measured — distance, bearing, and
 * timezone delta are real and independently verifiable; a millisecond number
 * we didn't benchmark would not be.
 */

export type CityFix = {
  name: string;
  lat: number;
  lon: number;
  /** Great-circle distance from Singapore, km (haversine, rounded). */
  km: number;
  /** Initial great-circle bearing from Singapore, degrees true. */
  bearing: number;
  /** Standard UTC offset, e.g. "+08:00". */
  utc: string;
  /** Hours offset from Singapore (SGT, UTC+8), signed. */
  deltaFromSgt: number;
};

export const SINGAPORE = { lat: 1.3521, lon: 103.8198, utc: "+08:00" } as const;

// Precomputed with a haversine/initial-bearing script against public lat/lon —
// see the singapore-vps-hosting redesign task notes for the calculation.
export const REGIONAL_CITIES: CityFix[] = [
  { name: "Kuala Lumpur", lat: 3.139, lon: 101.6869, km: 309, bearing: 310, utc: "+08:00", deltaFromSgt: 0 },
  { name: "Jakarta", lat: -6.2088, lon: 106.8456, km: 905, bearing: 158, utc: "+07:00", deltaFromSgt: -1 },
  { name: "Ho Chi Minh City", lat: 10.8231, lon: 106.6297, km: 1098, bearing: 16, utc: "+07:00", deltaFromSgt: -1 },
  { name: "Bangkok", lat: 13.7563, lon: 100.5018, km: 1427, bearing: 345, utc: "+07:00", deltaFromSgt: -1 },
  { name: "Manila", lat: 14.5995, lon: 120.9842, km: 2393, bearing: 51, utc: "+08:00", deltaFromSgt: 0 },
  { name: "Mumbai", lat: 19.076, lon: 72.8777, km: 3904, bearing: 302, utc: "+05:30", deltaFromSgt: -2.5 },
  { name: "Seoul", lat: 37.5665, lon: 126.978, km: 4672, bearing: 28, utc: "+09:00", deltaFromSgt: 1 },
  { name: "Tokyo", lat: 35.6762, lon: 139.6503, km: 5311, bearing: 40, utc: "+09:00", deltaFromSgt: 1 },
  { name: "Sydney", lat: -33.8688, lon: 151.2093, km: 6306, bearing: 133, utc: "+10:00", deltaFromSgt: 2 },
];

/** Equirectangular plot coordinates for the SVG plotting board, viewBox 0 0 1000 700. */
export function plot(lat: number, lon: number) {
  const lonMin = 68, lonMax = 157, latMin = -36, latMax = 39;
  const x = ((lon - lonMin) / (lonMax - lonMin)) * 1000;
  const y = ((latMax - lat) / (latMax - latMin)) * 700;
  return { x, y };
}

"use client";

import { useEffect, useRef, useState } from "react";
import styles from "./chart.module.css";
import { REGIONAL_CITIES, SINGAPORE, plot } from "./geo";

const ORIGIN = plot(SINGAPORE.lat, SINGAPORE.lon);
// A readable subset for the hero plot (the full set appears later in the range table).
const HERO_CITIES = REGIONAL_CITIES.filter((c) =>
  ["Jakarta", "Kuala Lumpur", "Manila", "Bangkok", "Mumbai", "Sydney", "Tokyo"].includes(c.name),
);

const MERIDIANS = [70, 90, 110, 130, 150];
const PARALLELS = [-30, -10, 10, 30];

/**
 * The hero's plotting sheet: a flat lat/long grid (not a globe or dotted world
 * map) with Singapore as the origin fix and ruled, tick-marked rhumb lines
 * radiating out to real regional cities at their real great-circle distance.
 * Course lines draw themselves in once, on first view; nothing loops or pulses.
 */
export function PlottingBoard() {
  const ref = useRef<HTMLDivElement | null>(null);
  const [armed, setArmed] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") {
      setArmed(true);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => entries.forEach((e) => e.isIntersecting && (setArmed(true), io.disconnect())),
      { threshold: 0.25 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <div ref={ref} className={styles.board}>
      <div className={styles.boardCaption}>
        <span>Plotting sheet — SGP1 fix</span>
        <span>{SINGAPORE.lat.toFixed(4)}°N&nbsp;&nbsp;{SINGAPORE.lon.toFixed(4)}°E</span>
      </div>
      <svg viewBox="0 0 1000 700" className="w-full h-auto" role="img" aria-label="Plotting sheet showing distances from Nxeon's Singapore datacenter to regional cities">
        {MERIDIANS.map((lon) => {
          const a = plot(-36, lon);
          const b = plot(39, lon);
          return <line key={lon} x1={a.x} y1={a.y} x2={b.x} y2={b.y} className={styles.gridLine} />;
        })}
        {PARALLELS.map((lat) => {
          const a = plot(lat, 68);
          const b = plot(lat, 157);
          return <line key={lat} x1={a.x} y1={a.y} x2={b.x} y2={b.y} className={styles.gridLine} />;
        })}

        {HERO_CITIES.map((c, i) => {
          const p = plot(c.lat, c.lon);
          const len = Math.hypot(p.x - ORIGIN.x, p.y - ORIGIN.y);
          const midX = (ORIGIN.x + p.x) / 2;
          const midY = (ORIGIN.y + p.y) / 2;
          return (
            <g key={c.name}>
              <line
                x1={ORIGIN.x}
                y1={ORIGIN.y}
                x2={p.x}
                y2={p.y}
                className={`${styles.courseLine} ${styles.courseLineAnim}`}
                style={{
                  strokeDashoffset: armed ? 0 : len,
                  transitionDelay: `${140 + i * 90}ms`,
                }}
              />
              <circle cx={p.x} cy={p.y} r={4.5} className={styles.cityDot} />
              <text x={p.x + 9} y={p.y - 7} className={styles.cityLabel}>
                {c.name}
              </text>
              <text x={midX + 6} y={midY} className={styles.distLabel}>
                {c.km.toLocaleString()} km
              </text>
            </g>
          );
        })}

        {/* Origin fix */}
        <circle cx={ORIGIN.x} cy={ORIGIN.y} r={13} fill="none" stroke="var(--vermillion)" strokeWidth={1.2} opacity={0.5} />
        <circle cx={ORIGIN.x} cy={ORIGIN.y} r={6} className={styles.originDot} />
        <text x={ORIGIN.x + 12} y={ORIGIN.y + 18} className={styles.distLabel} fontWeight={700}>
          SGP1
        </text>
      </svg>
    </div>
  );
}

import styles from "./chart.module.css";

/**
 * Small compass-rose mark used beside the hero eyebrow. The needle settles
 * once from -70° to true north on mount (see .needle / @keyframes settle in
 * chart.module.css) — a one-time instrument reading, not a continuous spin.
 */
export function CompassFix({ size = 34 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" aria-hidden className="flex-none">
      <circle cx="20" cy="20" r="18.5" fill="none" stroke="var(--ink)" strokeWidth="1.2" />
      <circle cx="20" cy="20" r="1.6" fill="var(--ink)" />
      {[0, 45, 90, 135, 180, 225, 270, 315].map((deg) => (
        <line
          key={deg}
          x1="20"
          y1="3"
          x2="20"
          y2={deg % 90 === 0 ? "6.5" : "5"}
          stroke="var(--ink)"
          strokeWidth={deg % 90 === 0 ? 1.3 : 0.8}
          transform={`rotate(${deg} 20 20)`}
        />
      ))}
      <g className={styles.needle}>
        <path d="M20 8 L23 20 L20 32 L17 20 Z" fill="none" />
        <path d="M20 8 L22.2 20 L20 20 Z" fill="var(--vermillion)" />
        <path d="M20 32 L17.8 20 L20 20 Z" fill="var(--ink)" />
      </g>
    </svg>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import styles from "./chart.module.css";

/**
 * Counts up to a real, precomputed value once the element scrolls into view —
 * an instrument-readout tick, not a decorative loop. Respects
 * prefers-reduced-motion by rendering the final value immediately.
 */
export function Odometer({ to, suffix = "" }: { to: number; suffix?: string }) {
  const ref = useRef<HTMLSpanElement | null>(null);
  const [value, setValue] = useState(0);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce || typeof IntersectionObserver === "undefined") {
      setValue(to);
      return;
    }

    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (!e.isIntersecting) continue;
          io.disconnect();
          const duration = 900;
          const start = performance.now();
          const tick = (now: number) => {
            const p = Math.min(1, (now - start) / duration);
            const eased = 1 - Math.pow(1 - p, 3);
            setValue(Math.round(to * eased));
            if (p < 1) requestAnimationFrame(tick);
          };
          requestAnimationFrame(tick);
        }
      },
      { threshold: 0.4 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [to]);

  return (
    <span ref={ref} className={styles.odo}>
      {value.toLocaleString()}
      {suffix}
    </span>
  );
}

import styles from "./chart.module.css";
import { REGIONAL_CITIES } from "./geo";
import { Odometer } from "./Odometer";

function fmtDelta(h: number): string {
  if (h === 0) return "same time";
  const sign = h > 0 ? "+" : "";
  return `${sign}${h}h`;
}

/**
 * The distance/timezone table that replaces the old page's "latency by
 * country" list. It intentionally does NOT quote millisecond figures Nxeon
 * has never benchmarked — every column here (km, true bearing, UTC offset) is
 * a real, independently checkable geographic fact.
 */
export function RangeTable() {
  return (
    <div className="overflow-x-auto">
      <table className={styles.rangeTable}>
        <caption>Range &amp; bearing from SGP1 — Singapore</caption>
        <thead>
          <tr>
            <th>City</th>
            <th>Great-circle distance</th>
            <th>True bearing</th>
            <th>Local time vs. Singapore</th>
          </tr>
        </thead>
        <tbody>
          {REGIONAL_CITIES.map((c) => (
            <tr key={c.name}>
              <td className={styles.serif} style={{ fontWeight: 600 }}>
                {c.name}
              </td>
              <td>
                <Odometer to={c.km} suffix=" km" />
              </td>
              <td>
                <span className={styles.bearingChip}>{c.bearing}° T</span>
              </td>
              <td>
                {c.utc} · {fmtDelta(c.deltaFromSgt)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import styles from "./chart.module.css";
import { RevealChart } from "./RevealChart";

function Glyph({ d }: { d: React.ReactNode }) {
  return (
    <svg viewBox="0 0 28 28" width="28" height="28" fill="none" stroke="currentColor" strokeWidth="1.4" className={styles.legendGlyph} aria-hidden>
      {d}
    </svg>
  );
}

const ITEMS: { term: string; def: string; glyph: React.ReactNode }[] = [
  {
