"use client";

import Link from "next/link";
import styles from "./chart.module.css";
import { RevealChart } from "./RevealChart";
import { useDisplayMoney } from "@/components/currency/CurrencyContext";
import type { PlanCard } from "@/components/marketing/PricingGrid";

/**
 * The pricing section, styled as a ruled cargo/spec manifest rather than a
 * row of rounded glowing cards. Figures are the live DB plans passed down
 * from page.tsx (db.plan.findMany) — nothing here is hardcoded copy.
 */
export function Manifest({ plans }: { plans: PlanCard[] }) {
  const money = useDisplayMoney();
  if (plans.length === 0) {
    return (
      <p className={`${styles.mono} text-sm`} style={{ color: "var(--ink-soft)" }}>
        Plans are being provisioned. Please check back shortly.
      </p>
    );
  }
  const popularIdx = Math.floor((plans.length - 1) / 2);

  return (
    <div className={styles.manifest}>
      {plans.map((p, i) => {
        const popular = i === popularIdx;
        const ramGB = p.ramMB / 1024;
        return (
          <RevealChart key={p.id} delay={i * 70} as="div" className={`${styles.manifestCol} ${popular ? styles.manifestColPopular : ""}`}>
            {popular && <span className={styles.seal}>Most&nbsp;booked&nbsp;fit</span>}
            <div className={styles.planName}>{p.name}</div>
            <div className={styles.planPrice}>
              {money(p.priceCents)}
              <sup>/mo</sup>
            </div>
            <div className={styles.planSpecs}>
              <div><span>vCPU</span><span>{p.cpuCores}</span></div>
              <div><span>Memory</span><span>{ramGB.toFixed(ramGB % 1 ? 1 : 0)} GB</span></div>
              <div><span>Storage</span><span>{p.diskGB} GB {p.storageTier === "hdd" ? "HDD" : "NVMe"}</span></div>
              <div><span>Bandwidth</span><span>{p.bandwidthTB} TB</span></div>
              <div><span>IPv4</span><span>Dedicated</span></div>
              <div><span>Region</span><span>SGP1</span></div>
            </div>
            <Link href="/register" className={styles.tab} style={{ marginTop: "1.4rem", width: "100%", justifyContent: "center" }}>
              Deploy now
            </Link>
          </RevealChart>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import styles from "./chart.module.css";

const STEPS = [
  { at: 0, title: "Sign up free", body: "No card required — open the deploy wizard." },
  { at: 14, title: "Deploy to SGP1", body: "Pick a one-click OS or app image, land in Singapore with a dedicated IP." },
  { at: 47, title: "SSH ready", body: "Full root, key or password auth — point DNS and you're live for APAC traffic." },
];

const TOTAL_SECONDS = 47;
const RADIUS = 54;
const CIRC = 2 * Math.PI * RADIUS;

/**
 * The "deploy in 47 seconds" section as an instrument dial + flight-log
 * transcript instead of numbered circles. The dial sweeps once, on first
 * view, from 0 to the real median deploy time (47s); log lines light up as
 * the sweep passes each step's real timestamp. Purely illustrative timing —
 * the sweep itself runs over ~2.4s of wall-clock so the reader isn't asked to
 * wait 47 real seconds to see it finish.
 */
export function DeploySequence() {
  const ref = useRef<HTMLDivElement | null>(null);
  const [seconds, setSeconds] = useState(0);
  const [done, setDone] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) {
      setSeconds(TOTAL_SECONDS);
      setDone(true);
      return;
    }
    if (typeof IntersectionObserver === "undefined") {
      setSeconds(TOTAL_SECONDS);
      setDone(true);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (!e.isIntersecting) continue;
          io.disconnect();
          const durationMs = 2400;
          const start = performance.now();
          const tick = (now: number) => {
            const p = Math.min(1, (now - start) / durationMs);
            setSeconds(Math.round(p * TOTAL_SECONDS));
            if (p < 1) requestAnimationFrame(tick);
            else setDone(true);
          };
          requestAnimationFrame(tick);
        }
      },
      { threshold: 0.4 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  const frac = seconds / TOTAL_SECONDS;
  const offset = CIRC * (1 - frac);

  return (
    <div ref={ref} className="grid gap-8 md:grid-cols-[auto_1fr] items-center">
      <svg width="140" height="140" viewBox="0 0 140 140" className={styles.dial} aria-hidden>
        <circle cx="70" cy="70" r={RADIUS} className={styles.dialTrack} strokeWidth="8" />
        <circle
          cx="70"
          cy="70"
          r={RADIUS}
          className={styles.dialHand}
          strokeWidth="8"
          strokeDasharray={CIRC}
          strokeDashoffset={offset}
        />
      </svg>
      <div className={styles.logPanel}>
        {STEPS.map((s) => {
          const active = seconds >= s.at;
          return (
            <div key={s.title} className={`${styles.logLine} ${active ? styles.logLineActive : ""}`}>
              <span className={styles.logTime}>{String(s.at).padStart(2, "0")}s</span>
              <span>
                <strong>{s.title}</strong>
                {active && done && s.at === TOTAL_SECONDS ? <span className={styles.logOk}> · ready</span> : null}
                <br />
                <span style={{ opacity: 0.8 }}>{s.body}</span>
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import styles from "./chart.module.css";
import { RevealChart } from "./RevealChart";

/** FAQ rendered as numbered chart marginalia rather than an accordion. */
export function Marginalia({ items }: { items: { q: string; a: string }[] }) {
  return (
    <div>
      {items.map((item, i) => (
        <RevealChart key={item.q} delay={i * 50} as="div" className={styles.margNote}>
          <span className={styles.margNum}>{String(i + 1).padStart(2, "0")}</span>
          <div>
            <div className={styles.margQ}>{item.q}</div>
            <p className={styles.margA}>{item.a}</p>
          </div>
        </RevealChart>
      ))}
    </div>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
