3	import { useEffect, useRef, useState } from "react";
4	import styles from "./chart.module.css";
5	
6	/**
7	 * Page-local scroll reveal: a "ruler unrolling" left-to-right clip-path wipe
8	 * (see .reveal / .revealShown in chart.module.css) — deliberately not the
9	 * shared fade+rise <Reveal> used by the rest of the site, and not the old
10	 * radar-sweep motion either. Falls back to fully visible without JS or when
11	 * IntersectionObserver is unavailable.
12	 */
13	export function RevealChart({
14	  children,
15	  delay = 0,
16	  className = "",
17	  as: Tag = "div",
18	  style,
19	}: {
20	  children: React.ReactNode;
21	  delay?: number;
22	  className?: string;
23	  as?: React.ElementType;
24	  style?: React.CSSProperties;
25	}) {
26	  const ref = useRef<HTMLElement | null>(null);
27	  const [shown, setShown] = useState(false);
28	
29	  useEffect(() => {
30	    const el = ref.current;
31	    if (!el) return;
32	    if (typeof IntersectionObserver === "undefined") {
33	      setShown(true);
34	      return;
35	    }
36	    const io = new IntersectionObserver(
37	      (entries) => {
38	        for (const e of entries) {
39	          if (e.isIntersecting) {
40	            setShown(true);
41	            io.disconnect();
42	          }
43	        }
44	      },
45	      { threshold: 0.15, rootMargin: "0px 0px -60px 0px" },
46	    );
47	    io.observe(el);
48	    return () => io.disconnect();
49	  }, []);
50	
51	  return (
52	    <Tag
53	      ref={ref}
54	      className={`${styles.reveal} ${shown ? styles.revealShown : ""} ${className}`}
55	      style={{ transitionDelay: `${delay}ms` }}
56	    >
57	      {children}
58	    </Tag>
59	  );
60	}
