useEffect(() => {
  const el = ref.current;
  if (!el) return;
  if (typeof IntersectionObserver === "undefined") {
    setShown(true);
    return;
  }
  // threshold MUST be 0 here, not a ratio like 0.15: the element being
  // observed is the one carrying `clip-path: inset(...)` from .reveal, and
  // Chromium computes intersectionRatio against the CLIPPED (i.e. ~zero,
  // pre-reveal) painted area rather than the layout box. `isIntersecting`
  // still reflects the real, unclipped geometric overlap, so a ratio-based
  // threshold silently never fires while `isIntersecting` behaves
  // correctly — use that instead of a ratio crossing.
  const io = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        if (e.isIntersecting) {
          setShown(true);
          io.disconnect();
        }
      }
    },
    { threshold: 0, rootMargin: "0px 0px -60px 0px" },
  );
  io.observe(el);
  return () => io.disconnect();
}, []);

